foreach(var hero85 in Enum.GetValues<HeroId>()){game.StartNew(hero85,Difficulty.Sopravvivenza);ResetEventRules();screen=Screen.World;EnterMap("casa_olmo",14,16);BeginPentesileaDialogue();C(speaker=="????","first speaker");var ls=pentesileaLines.Where(x=>x.Portrait==PentesileaPortrait).ToArray();int reveal=Array.FindIndex(ls,x=>x.Text.StartsWith("Pentesilea."));C(reveal==3,"reveal order");C(ls.Take(reveal).All(x=>x.Speaker=="????"),"hidden name");C(ls.Skip(reveal).All(x=>x.Speaker=="Pentesilea"),"revealed name");}
